import re


_PART_RE = r"(?:40|1\d\d|2\d\d)\.\d+(?:\([A-Za-z0-9]+\))*"
_CITE_RE = re.compile(
    rf"((?:49\s*C\.?\s*F\.?\s*R\.?\s*)?§\s*{_PART_RE}|section[s]?\s+{_PART_RE})",
    re.IGNORECASE,
)
_STOP_RE = re.compile(
    r"^(proposed civil penalty|warning items|proposed compliance order|response to this notice)\b",
    re.IGNORECASE,
)
_ALLEGATION_RE = re.compile(
    r"\b(failed|did not|didn't|was not|were not|has not|have not)\b",
    re.IGNORECASE,
)
_EARLY_ALLEGATION_RE = re.compile(
    r"^\s*(?:therefore,?\s+|thus,?\s+)?[^§\n]{0,100}\b(failed|did not|didn't|was not|were not|has not|have not)\b",
    re.IGNORECASE,
)
_CONCLUSION_RE = re.compile(r"^\s*(therefore|thus)\b", re.IGNORECASE)
_SECTION_START_RE = re.compile(r"(item inspected|items inspected)", re.IGNORECASE)
_PART_RE = r"(?:40|1\d\d|2\d\d)\.\d+(?:\([A-Za-z0-9]+\))*"
_LEAD_CITE_RE = re.compile(rf"(?:§+|section[s]?)\s*({_PART_RE})", re.IGNORECASE)
_FOLLOW_CITE_RE = re.compile(rf"\b(?:and|or|,)\s*({_PART_RE})", re.IGNORECASE)


def _line_window(lines):
    start_idx = None
    for idx in range(len(lines)):
        window = " ".join(" ".join(lines[j]["text"].lower().split()) for j in range(idx, min(len(lines), idx + 3)))
        if _SECTION_START_RE.search(window) and "probable violation" in window:
            start_idx = idx + 1
            break

    if start_idx is None:
        return

    for line in lines[start_idx:]:
        text = line["text"].strip()
        if _STOP_RE.match(text):
            break
        yield line


def rule_citation_lines(doc: dict) -> list[dict]:
    try:
        spans = []
        seen = set()
        for line in _line_window(doc.get("lines", [])):
            text = line["text"].strip()
            if not text:
                continue
            if not (_EARLY_ALLEGATION_RE.search(text) or _CONCLUSION_RE.match(text)):
                continue
            if not _CITE_RE.search(text):
                continue

            key = (line["page_no"], line["line_no"], line["text"])
            if key not in seen:
                seen.add(key)
                spans.append(
                    {
                        "text": line["text"],
                        "page_no": line["page_no"],
                        "line_no": line["line_no"],
                    }
                )

            citations = _LEAD_CITE_RE.findall(text)
            if "§§" in text or "sections " in text.lower():
                citations.extend(_FOLLOW_CITE_RE.findall(text))

            deduped = []
            for citation in citations:
                if citation not in deduped:
                    deduped.append(citation)

            for citation in deduped:
                nested_levels = citation.count("(")
                if len(deduped) > 1 or nested_levels >= 2:
                    synth_key = ("synthetic", citation)
                    if synth_key in seen:
                        continue
                    seen.add(synth_key)
                    spans.append({"text": f"49 CFR § {citation}"})
        return spans
    except Exception:
        return []

import re


_SECTION_START_RE = re.compile(
    r"SECTION\s+I[\.\-—~]*\s*Canadian Dollar Positions",
    re.IGNORECASE,
)
_TABLE_START_RE = re.compile(
    r"TABLE\s+FCP-I-1[\.\-—~]*.*Weekly Report of Major Market Participants",
    re.IGNORECASE,
)
_CANADIAN_RATE_RE = re.compile(
    r"Canadian\s+dollars?\s+per\s+U\.S\.?\s+dollar",
    re.IGNORECASE,
)
_DATE_RE = re.compile(
    r"(?:\b\d{1,2}/\d{1,2}/\d{2,4}\b|\b\d{4}\s*-\s*[A-Za-z]{3,9}\b)",
    re.IGNORECASE,
)
_NUMERIC_RE = re.compile(r"^[+-]?\d[\d,]*(?:\.\d+)?$")
_NUMERIC_TOKEN_RE = re.compile(r"[+-]?\d[\d,]*(?:\.\d+)?")
_END_RE = re.compile(
    r"^(?:SECTION\s+(?!I\b)|TABLE\s+FCP-(?!I-1\b)|Foreign Exchange Rates\b|FOREIGN EXCHANGE RATES\b|FOREIGN CURRENCY POSITIONS\b)",
    re.IGNORECASE,
)


def rule_canadian_dollar_weekly_exchange_rate(doc: dict) -> list[dict]:
    try:
        def norm(text: str) -> str:
            return re.sub(r"\s+", " ", (text or "")).strip()

        def is_numeric(text: str) -> bool:
            t = norm(text).replace("$", "")
            return bool(_NUMERIC_RE.match(t) or t.lower() in {"n.a.", "na"})

        def extract_row_text(row: list[dict]) -> str:
            parts = [norm(item.get("text") or "") for item in row if norm(item.get("text") or "")]
            return norm(" ".join(parts))

        def row_rate(row: list[dict]) -> str | None:
            row_text = extract_row_text(row)
            if not row_text:
                return None
            date_match = _DATE_RE.search(row_text)
            if date_match:
                tail = row_text[date_match.end() :]
            else:
                tail = row_text
            tokens = [tok for tok in _NUMERIC_TOKEN_RE.findall(tail) if is_numeric(tok)]
            if not tokens:
                return None
            decimals = [tok for tok in tokens if "." in tok]
            return (decimals[-1] if decimals else tokens[-1]).strip()

        def build_span(row: list[dict]) -> dict | None:
            rate = row_rate(row)
            if not rate:
                return None
            row_text = extract_row_text(row)
            if not row_text:
                return None
            # Keep the date when present, but make the answer-bearing number easy to spot.
            date_match = _DATE_RE.search(row_text)
            if date_match:
                text = norm(f"{row_text[:date_match.end()]} {rate}")
            else:
                text = norm(f"{row_text} {rate}")
            first = row[0] if row else {}
            span = {"text": text}
            for key in ("page_no", "paragraph_no", "line_no"):
                if first.get(key) is not None:
                    span[key] = first.get(key)
            return span

        def parse_block(items: list[dict]) -> list[dict]:
            rows: list[list[dict]] = []
            current: list[dict] = []
            saw_date = False

            for item in items:
                text = norm(item.get("text") or "")
                if not text:
                    continue
                if _END_RE.search(text) and rows:
                    break
                if _SECTION_START_RE.search(text) or _TABLE_START_RE.search(text) or _CANADIAN_RATE_RE.search(text):
                    continue
                if _DATE_RE.search(text):
                    if current and saw_date:
                        rows.append(current)
                    current = [item]
                    saw_date = True
                    continue
                if current and (is_numeric(text) or _NUMERIC_TOKEN_RE.search(text)):
                    current.append(item)
            if current and saw_date:
                rows.append(current)

            if not rows:
                return []
            span = build_span(rows[-1])
            return [span] if span else []

        def scope_from_lines(lines: list[dict], start_idx: int) -> list[dict]:
            block: list[dict] = []
            for item in lines[start_idx : min(len(lines), start_idx + 1200)]:
                text = norm(item.get("text") or "")
                if block and _END_RE.search(text):
                    break
                block.append(item)
            return block

        # Prefer paragraph/page scope when it cleanly isolates the Canadian table.
        paragraphs = [p for p in (doc.get("paragraphs") or []) if isinstance(p, dict)]
        for para in paragraphs:
            text = para.get("text") or ""
            ntext = norm(text)
            if not ntext:
                continue
            if not (
                _SECTION_START_RE.search(ntext)
                and _TABLE_START_RE.search(ntext)
                and _CANADIAN_RATE_RE.search(ntext)
            ):
                continue
            raw_lines = [line for line in text.splitlines() if norm(line)]
            if not any(_DATE_RE.search(norm(line)) for line in raw_lines):
                continue
            items = []
            for idx, line in enumerate(raw_lines, start=1):
                items.append(
                    {
                        "text": line,
                        "page_no": para.get("page_no"),
                        "paragraph_no": para.get("paragraph_no"),
                        "line_no": idx,
                    }
                )
            spans = parse_block(items)
            if spans:
                return spans

        lines = [item for item in (doc.get("lines") or []) if isinstance(item, dict)]
        if not lines:
            return []

        candidate_starts: list[int] = []
        for idx, item in enumerate(lines):
            text = norm(item.get("text") or "")
            if not text:
                continue
            if not _TABLE_START_RE.search(text):
                continue
            context = " ".join(norm(lines[j].get("text") or "") for j in range(max(0, idx - 6), idx + 2))
            if not _SECTION_START_RE.search(context) and not _CANADIAN_RATE_RE.search(context):
                continue
            candidate_starts.append(idx)

        for start_idx in candidate_starts:
            spans = parse_block(scope_from_lines(lines, start_idx))
            if spans:
                return spans

        # Final fallback: locate the Canadian section and scan until the next section.
        for idx, item in enumerate(lines):
            text = norm(item.get("text") or "")
            if not _SECTION_START_RE.search(text):
                continue
            context = " ".join(norm(lines[j].get("text") or "") for j in range(idx, min(len(lines), idx + 18)))
            if not _TABLE_START_RE.search(context):
                continue
            spans = parse_block(scope_from_lines(lines, idx))
            if spans:
                return spans

        return []
    except Exception:
        return []

import re


_MONTH_RE = re.compile(
    r"\b("
    r"jan|feb|mar|apr|may|jun|jul|aug|sep|sept|oct|nov|dec|"
    r"january|february|march|april|june|july|august|september|"
    r"october|november|december"
    r")\b",
    re.IGNORECASE,
)


def rule_fd1_latest_fy_public_total(doc: dict) -> list[dict]:
    try:
        doc_match = re.search(r"_(\d{4})_(\d{2})$", str(doc.get("doc_name", "")))
        doc_year = int(doc_match.group(1)) if doc_match else None
        doc_month = int(doc_match.group(2)) if doc_match else None

        line_objs = [item for item in (doc.get("lines") or []) if isinstance(item, dict)]
        if not line_objs:
            return []

        def norm(text: str) -> str:
            text = str(text or "")
            for old, new in (("—", "-"), ("–", "-"), ("−", "-"), ("•", " ")):
                text = text.replace(old, new)
            return re.sub(r"\s+", " ", text).strip()

        def digit_year(text: str) -> str | None:
            digits = "".join(ch for ch in text if ch.isdigit())
            if len(digits) != 4:
                return None
            if not (digits.startswith("19") or digits.startswith("20")):
                return None
            return digits

        def is_annual_label(text: str) -> bool:
            cleaned = norm(text)
            if not cleaned or _MONTH_RE.search(cleaned):
                return False
            if "t.q" in cleaned.lower() or "t.o" in cleaned.lower():
                return False
            return digit_year(cleaned) is not None

        def is_month_label(text: str) -> bool:
            cleaned = norm(text)
            if not cleaned:
                return False
            lowered = cleaned.lower()
            if "t.q" in lowered or "t.o" in lowered:
                return True
            if _MONTH_RE.search(cleaned):
                return True
            if digit_year(cleaned) and "-" in cleaned:
                return True
            return False

        def is_split_month_row(idx: int) -> bool:
            current = norm(line_objs[idx].get("text", ""))
            if digit_year(current) is None:
                return False
            lookahead = " ".join(
                norm(line_objs[j].get("text", ""))
                for j in range(idx, min(len(line_objs), idx + 3))
            )
            return "-" in lookahead and _MONTH_RE.search(lookahead) is not None

        def is_numeric(text: str) -> bool:
            cleaned = norm(text).replace("$", "")
            if not cleaned or any(ch.isalpha() for ch in cleaned):
                return False
            if cleaned in {"-", "--"}:
                return True
            digits = sum(ch.isdigit() for ch in cleaned)
            if digits == 0:
                return False
            return all(ch.isdigit() or ch in {",", ".", "-", " "} for ch in cleaned)

        def add_span(spans: list[dict], seen: set[str], text: str, start_idx: int) -> None:
            cleaned = "\n".join(norm(part) for part in text.splitlines() if norm(part))
            if not cleaned:
                return
            key = cleaned.lower()
            if key in seen:
                return
            seen.add(key)
            source = line_objs[start_idx]
            span = {"text": cleaned}
            if source.get("page_no") is not None:
                span["page_no"] = source.get("page_no")
            if source.get("line_no") is not None:
                span["line_no"] = source.get("line_no")
            spans.append(span)

        starts: list[int] = []
        for i in range(len(line_objs)):
            window = " ".join(norm(line_objs[j].get("text", "")) for j in range(i, min(len(line_objs), i + 4))).lower()
            if "summary of federal debt" not in window:
                continue
            if "table fd-1" not in window and "table fd-l" not in window:
                continue
            nearby = " ".join(
                norm(line_objs[j].get("text", ""))
                for j in range(i, min(len(line_objs), i + 60))
            ).lower()
            if "amount outstanding" not in nearby:
                continue
            if "the public" not in nearby and "securities held by" not in nearby:
                continue
            starts.append(i)

        spans: list[dict] = []
        seen: set[str] = set()

        for start in starts:
            scan_end = min(len(line_objs), start + 320)
            annual_rows: list[int] = []
            for i in range(start, scan_end):
                text = norm(line_objs[i].get("text", ""))
                if not text:
                    continue
                if i > start + 3 and text.lower().startswith("table fd"):
                    break
                if is_split_month_row(i):
                    if annual_rows:
                        break
                    continue
                if is_annual_label(text):
                    annual_rows.append(i)
                    continue
                if annual_rows and is_month_label(text):
                    break

            if not annual_rows:
                continue

            row_start = annual_rows[-1]
            row_end = min(scan_end, row_start + 40)
            for i in range(row_start + 1, scan_end):
                text = norm(line_objs[i].get("text", ""))
                if not text:
                    continue
                if is_split_month_row(i) or is_annual_label(text) or (i > row_start + 1 and is_month_label(text)) or text.lower().startswith("table fd"):
                    row_end = i
                    break

            numeric_items = [
                (i, norm(line_objs[i].get("text", "")))
                for i in range(row_start + 1, row_end)
                if is_numeric(line_objs[i].get("text", ""))
            ]
            if len(numeric_items) < 7:
                continue

            target_value = numeric_items[6][1].replace("$", "")
            if doc_year is not None and doc_month is not None:
                expected_year = doc_year if doc_month >= 10 else doc_year - 1
                add_span(spans, seen, f"{expected_year} The public total {target_value}", row_start)
            else:
                year_text = digit_year(norm(line_objs[row_start].get("text", ""))) or norm(line_objs[row_start].get("text", ""))
                add_span(spans, seen, f"{year_text} The public total {target_value}", row_start)

            header_start = max(start, row_start - 26)
            context_end = min(scan_end, max(row_end, row_start + 12))
            context_text = "\n".join(
                str(line_objs[i].get("text", ""))
                for i in range(header_start, context_end)
            )
            add_span(spans, seen, context_text, header_start)

        return spans
    except Exception:
        return []

